// MEMORY-GATES MG6 (memory epoch 4, mini-estcal2, 2026-11-17): the offline estimate against what ENGINE-MEMORY EM11's
// phone chain predicts from native WebKit for each pinned product. A model change that reads any zone under EM11's upper
// bound fails here. The rows are regenerated by `memory-calibration.golden-gen.mjs` from the real products whenever the
// model changes, which bumps MEMORY_EPOCH.
import { expect, test } from 'vitest'

import { bootPhoneBytes } from './boot-memory-cost.ts'
import golden from './memory-calibration.golden.json' with { type: 'json' }
import { MEMORY_EPOCH } from './memory-epoch.ts'
import { MEMORY_HARD_BYTES } from './memory-line.ts'

type Zone = Readonly<(typeof golden.zones)[number]>

const MB = 1_000_000
/** EM11's runs are noisy (Pine's loading upper bound read 1,532 to 1,738 MB over three cold runs) and the light zones
 *  share one engine term with Sunscar Dunes, whose held bitmaps read ~180 MB over its terms; the ceiling keeps a model
 *  from buying safety with a blanket margin. */
const CEILING = 1.3
const ZONES = 10
/** J410 (Jake, 2026-11-17): engine's PHONE_PLAYING_BYTES, the envelope every zone targets while playing. */
const PHONE_PLAYING_BYTES = 1e9
/** The one zone EM11 puts under the 1.5 GB line that the estimate refuses: Driftwood, 1,434 MB at EM11's upper bound and
 *  1,234 MB central. No linear model of these terms both covers Sunscar Dunes, Nalati and Nine and lets it under. */
const REFUSED_OVER_EM11 = new Set(['driftwood-isle'])
/** MG11's ten zones: Showcase ships Ink Cel and Pastel, and Open Plots its 17 plots. */
const SHOWCASE = new Set(['ink-cel-valley', 'pastel-plain'])

// oxlint-disable-next-line typescript/prefer-readonly-parameter-types -- a JSON row, only read
function zoneOf(zone: Zone): string {
  if (zone.slug.startsWith('open-plot-')) {
    return 'open-plots'
  }
  return SHOWCASE.has(zone.slug) ? 'showcase' : zone.slug
}

test('MG6: the paired table was generated by the current memory model', (): void => {
  expect(
    golden.epoch,
    'regenerate memory-calibration.golden.json after a model change',
  ).toBe(MEMORY_EPOCH)
  expect(new Set(golden.zones.map(zoneOf)).size).toBe(ZONES)
  for (const zone of golden.zones) {
    expect(bootPhoneBytes(zone.terms), zone.slug).toEqual({
      playing: zone.playing,
      loading: zone.loading,
    })
  }
})

test('MG6: no zone is estimated under EM11 upper bound, nor far over it', (): void => {
  for (const zone of golden.zones) {
    for (const [estimate, high] of [
      [zone.playing, zone.em11.playingHighMB],
      [zone.loading, zone.em11.loadingHighMB],
    ] as const) {
      expect(
        estimate,
        `${zone.slug} under EM11's upper bound`,
      ).toBeGreaterThanOrEqual(high * MB)
      expect(
        estimate / (high * MB),
        `${zone.slug} far over EM11's upper bound`,
      ).toBeLessThanOrEqual(CEILING)
    }
  }
})

test('MG6 / J410: the estimate keeps EM11 verdict on the playing envelope and the loading line', (): void => {
  for (const zone of golden.zones) {
    expect(zone.playing <= PHONE_PLAYING_BYTES, zone.slug).toBe(
      zone.em11.playingHighMB * MB <= PHONE_PLAYING_BYTES,
    )
    expect(zone.loading <= MEMORY_HARD_BYTES, zone.slug).toBe(
      zone.em11.loadingHighMB * MB <= MEMORY_HARD_BYTES &&
        !REFUSED_OVER_EM11.has(zone.slug),
    )
  }
})
